const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define countries
  const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');
  const namibia = countries.filter(ee.Filter.eq('country_na', 'Namibia')).geometry();
  const zimbabwe = countries.filter(ee.Filter.eq('country_na', 'Zimbabwe')).geometry();

  // MODIS NDVI collection (16-day composite, 250m)
  const modis = ee.ImageCollection('MODIS/006/MOD13Q1')
    .select('NDVI');

  // Target period: Feb 21-28, 2019
  const target2019 = modis
    .filterDate('2019-02-21', '2019-03-01')
    .filterBounds(namibia.union(zimbabwe));

  // Long-term average: Feb 21-28, 2003-2017
  const longTermImages = [];
  for (let year = 2003; year <= 2017; year++) {
    const yearCol = modis
      .filterDate(`${year}-02-21`, `${year}-03-01`)
      .filterBounds(namibia.union(zimbabwe));
    if (yearCol.size().getInfo() > 0) {
      longTermImages.push(yearCol.mean());
    }
  }

  // Check if we have data
  const target2019Size = target2019.size().getInfo();
  console.log(`Target 2019 images: ${target2019Size}`);

  if (target2019Size === 0) {
    console.log('No data for 2019 period.');
    console.log('<answer>C1</answer>');
    return;
  }

  if (longTermImages.length === 0) {
    console.log('No data for long-term average period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Calculate means
  const img2019 = target2019.mean().multiply(0.0001); // MODIS scale factor
  const imgLongTerm = ee.ImageCollection(longTermImages).mean().multiply(0.0001);

  // Calculate statistics for both countries
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  // Namibia 2019
  const nam2019Stats = img2019.reduceRegion({
    reducer: reducer,
    geometry: namibia,
    scale: 3000,
    maxPixels: 1e9
  });
  const nam2019Mean = nam2019Stats.get('NDVI_mean').getInfo();
  const nam2019Count = nam2019Stats.get('NDVI_count').getInfo();

  // Namibia long-term
  const namLTStats = imgLongTerm.reduceRegion({
    reducer: reducer,
    geometry: namibia,
    scale: 3000,
    maxPixels: 1e9
  });
  const namLTMean = namLTStats.get('NDVI_mean').getInfo();
  const namLTCount = namLTStats.get('NDVI_count').getInfo();

  // Zimbabwe 2019
  const zim2019Stats = img2019.reduceRegion({
    reducer: reducer,
    geometry: zimbabwe,
    scale: 3000,
    maxPixels: 1e9
  });
  const zim2019Mean = zim2019Stats.get('NDVI_mean').getInfo();
  const zim2019Count = zim2019Stats.get('NDVI_count').getInfo();

  // Zimbabwe long-term
  const zimLTStats = imgLongTerm.reduceRegion({
    reducer: reducer,
    geometry: zimbabwe,
    scale: 3000,
    maxPixels: 1e9
  });
  const zimLTMean = zimLTStats.get('NDVI_mean').getInfo();
  const zimLTCount = zimLTStats.get('NDVI_count').getInfo();

  // Check for valid pixels
  if (nam2019Count === 0 || namLTCount === 0 || zim2019Count === 0 || zimLTCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for null values
  if (nam2019Mean === null || namLTMean === null || zim2019Mean === null || zimLTMean === null) {
    console.log('Calculation returned null values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Calculate anomalies
  const namAnomaly = nam2019Mean - namLTMean;
  const zimAnomaly = zim2019Mean - zimLTMean;

  console.log(`Namibia 2019 NDVI: ${nam2019Mean.toFixed(3)} (${nam2019Count} pixels)`);
  console.log(`Namibia LT Avg NDVI: ${namLTMean.toFixed(3)} (${namLTCount} pixels)`);
  console.log(`Namibia Anomaly: ${namAnomaly.toFixed(3)}`);
  console.log(`Zimbabwe 2019 NDVI: ${zim2019Mean.toFixed(3)} (${zim2019Count} pixels)`);
  console.log(`Zimbabwe LT Avg NDVI: ${zimLTMean.toFixed(3)} (${zimLTCount} pixels)`);
  console.log(`Zimbabwe Anomaly: ${zimAnomaly.toFixed(3)}`);

  // More negative anomaly = worse condition
  if (namAnomaly < zimAnomaly) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
